GetWaldaPhraseInputCase.body:
if (inputPtr[0] == EOS)
        return PHRASE_EMPTY;


    if (StringCompare(inputPtr, GetWaldaPhrasePtr()) == 0)
        return PHRASE_NO_CHANGE;


